}

.skeleton-text.large {
  height: 2rem;
  width: 70%;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* View Transitions */

/* Default page transition: slide in from right (forward navigation) */
::view-transition-old(root) {
  animation: slideOutLeft 300ms ease-in-out;
}

::view-transition-new(root) {
  animation: slideInRight 300ms ease-in-out;
}

/* Shared element transitions for product images */
::view-transition-group(*) {
  animation-duration: 400ms;
  animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
}

::view-transition-old(*),
::view-transition-new(*) {
  mix-blend-mode: normal;
}

/* Suspense content fade-in */
.product-info,
.product-grid {
  view-transition-name: content;
}

::view-transition-old(content) {
  animation: fadeOut 200ms ease-out;
}

::view-transition-new(content) {
  animation: fadeIn 300ms ease-in;
}

/* Reverse direction for back navigation */
html.back-navigation::view-transition-old(root) {
  animation: slideOutRight 300ms ease-in-out;
}

html.back-navigation::view-transition-new(root) {
  animation: slideInLeft 300ms ease-in-out;
}

/* Directional slide animations */
@keyframes slideOutLeft {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(-30px);
    opacity: 0;
  }
}

@keyframes slideInRight {
  from {
    transform: translateX(30px);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes slideOutRight {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(30px);
    opacity: 0;
  }
}

@keyframes slideInLeft {
  from {
    transform: translateX(-30px);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes fadeOut {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

/* Respect prefers-reduced-motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  ::view-transition-group(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }
}
